import React, { useEffect, useState } from 'react';
import { Menu, X } from 'lucide-react';
import { nav } from '../data/content';

export default function Header({ activeSection, onNavClick }) {
  const [open, setOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 4);
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  useEffect(() => {
    if (!open) return;
    const onKey = (e) => e.key === 'Escape' && setOpen(false);
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open]);

  const handleClick = (id) => {
    onNavClick(id);
    setOpen(false);
  };

  return (
    <header className={`nav-material fixed top-0 inset-x-0 z-50 ${scrolled || open ? 'is-scrolled' : ''}`}>
      <div className="max-w-prose mx-auto px-6 h-14 flex items-center justify-between">
        <a
          href="#top"
          onClick={(e) => { e.preventDefault(); handleClick('top'); }}
          className="press font-semibold tracking-tight text-zinc-900 rounded-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-400"
        >
          Chetanya Makkar
        </a>

        <nav className="hidden sm:flex items-center gap-5 text-sm">
          {nav.map((item) => (
            <a
              key={item.id}
              href={`#${item.id}`}
              onClick={(e) => { e.preventDefault(); handleClick(item.id); }}
              aria-current={activeSection === item.id ? 'true' : undefined}
              className={`press inline-block rounded-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-400 ${
                activeSection === item.id
                  ? 'text-orange-600'
                  : 'text-zinc-500 hover:text-zinc-900'
              }`}
            >
              {item.label}
            </a>
          ))}
        </nav>

        <button
          onClick={() => setOpen((o) => !o)}
          aria-label="Toggle menu"
          aria-expanded={open}
          aria-controls="mobile-menu"
          className="press sm:hidden p-1.5 -mr-1.5 rounded-md text-zinc-600 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-400"
        >
          {open ? <X size={18} /> : <Menu size={18} />}
        </button>
      </div>

      <div id="mobile-menu" className={`menu sm:hidden ${open ? 'menu-open' : ''}`} aria-hidden={!open}>
        <div>
          <nav className="border-t border-zinc-100 px-6 py-3 flex flex-col gap-3 text-sm">
            {nav.map((item) => (
              <a
                key={item.id}
                href={`#${item.id}`}
                tabIndex={open ? 0 : -1}
                onClick={(e) => { e.preventDefault(); handleClick(item.id); }}
                className={`press origin-left ${activeSection === item.id ? 'text-orange-600' : 'text-zinc-500'}`}
              >
                {item.label}
              </a>
            ))}
          </nav>
        </div>
      </div>
    </header>
  );
}
